        String pattern = "^(https?:\\/\\/)?([a-zA-Z0-9.-]+\\.[a-zA-Z]{2,}\\/[a-zA-Z0-9.-]+)*([a-zA-Z0-9?&=_-]+)$";
        Pattern regex = Pattern.compile(pattern);
        Matcher matcher = regex.matcher(url);
        return matcher.matches();
    }
